mapper.update:
UPDATE user_items ui
JOIN items i ON ui.item_id = i.item_id
SET ui.is_equipped = FALSE,
    ui.updated_at = NOW()
WHERE ui.user_id = #{userId}
  AND i.slot = #{slot}

mapper.select:
SELECT item_id AS itemId, name, slot, image_url AS imageUrl, price, is_purchasable AS purchasable
FROM items
WHERE is_purchasable = TRUE

    AND slot = #{category}

ORDER BY item_id DESC
LIMIT #{limit} OFFSET #{offset}
